  "civId": "occident",
  "periodId": "occ_roman",
  "civName": "Occident chrétien & moderne",
  "civilization": "France (Corse - Art roman pisan du Nebbio)",
  "subpart": "La féerie bichrome de calcaire et serpentine : gardien accroupi, Tentation d'Ève, porche roman et modillons zoomorphes",
  "date": "XIIe siècle (v. 1140 – 1180)",
  "dateDisplay": "XIIe siècle (v. 1140 – 1180)",
  "century": "XIIe siècle",
  "centuryDisplay": "XIIe s.",
  "centuryNumeric": 1160,
  "format": "Ensemble sculptural et reliefs incrustés en calcaire et serpentine (4 vues)",
  "dimensions": "Édifice complet et reliefs muraux",
  "site": "Église San Michele, Murato (Nebbio, Haute-Corse, France)",
  "originSite": "Murato (Nebbio, Corse)",
